WITH flattened_attrs AS (SELECT id, ship_to, attributes, attributes['gift'] AS gift, ship_to.country AS ship_country FROM carts) SELECT ship_country, COUNT(*) AS cnt, SIZE(COLLECT_SET(ship_country)) AS num_ship_countries, SIZE(COLLECT_SET(ship_country)) AS num_ship_countries_2, SORT_ARRAY(COLLECT_SET(ship_country)) AS ship_country_list, COUNT(DISTINCT ship_country) AS distinct_ship_countries, COUNT(CASE WHEN ship_country = 'US' THEN 1 END) AS us_count FROM flattened_attrs GROUP BY ship_country ORDER BY us_count DESC
